    if random.random() < self.mutation_rate * 2:
        possible_values = [v for v in self.search_space[gene_name] if v != child_value]
        if possible_values:
            child_value = random.choice(possible_values)

    # Enhance diversity by choosing a value that is not the most common among parents
    parent_values = [parent1_value, parent2_value]
    if child_value in parent_values:
